
import { Component, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { LanguageService } from '../../../services/language.service';
import { SITE_CONTENT } from '../../site-content';
import { TourPage, getTourContent } from '../tour-content';

@Component({
  selector: 'app-afterwork',
  templateUrl: './afterwork.component.html',
  styleUrls: ['./afterwork.component.scss'],
})
export class AfterworkComponent implements OnInit, OnDestroy {
  tour: TourPage = getTourContent('fr', 'afterwork-en-mer');
  private languageSub?: Subscription;

  constructor(private languageService: LanguageService) {}

  ngOnInit(): void {
    this.languageSub = this.languageService.language$.subscribe((language) => {
      this.tour = getTourContent(language, 'afterwork-en-mer');
    });
  }

  ngOnDestroy(): void {
    this.languageSub?.unsubscribe();
  }
}
